-- V038: ask_user supports ui=dropdown (HTML select) + synonym guidance for ddl/combobox.
-- Idempotent UPDATE of platform-multi-agent ask_user tool metadata.

UPDATE dbo.AppAgentLibraryTool
SET ToolDescription = N'Ask the user a structured question and wait for their answer (Interactive only). mode=text|single_choice|multi_choice. single_choice + optionsJson REQUIRED for choices (never list choices only in prompt). ui=button_group (one-click buttons, default menus) | radio (radio+Submit) | dropdown (HTML drop-down+Submit). Synonyms for dropdown: ddl, drop down, combobox, option list, select list — when the instruction uses those words, set ui=dropdown. layout=vertical|horizontal for button_group. fieldsJson type=text|select. Optionally merge via contextKey.',
    ParameterSchemaJson = N'{"type":"object","properties":{"prompt":{"type":"string","description":"Question shown to the user. If text mentions ddl/dropdown/combobox/option list, prefer ui=dropdown."},"mode":{"type":"string","description":"text | single_choice | multi_choice"},"fieldsJson":{"type":"string","description":"JSON array of {name,label,required?,type?,options?} — type=text|select; select options LookupItemDto [{id,display}]"},"optionsJson":{"type":"string","description":"JSON array of LookupItemDto {id,display} for choice modes"},"contextKey":{"type":"string","description":"Optional shared-context key to merge answers into"},"ui":{"type":"string","description":"radio | button_group | dropdown (aliases: ddl, drop down, combobox, option list, select). button_group one-click; dropdown HTML select+Submit; only for single_choice"},"layout":{"type":"string","description":"vertical (default) | horizontal — button_group only"}},"required":["prompt"]}'
WHERE LibraryKey = N'platform-multi-agent' AND ToolName = N'ask_user';
GO
